CREATE POLICY "Signed in read facility project objects" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'facility-project-files');
CREATE POLICY "Facility editors upload project objects" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'facility-project-files' AND EXISTS (SELECT 1 FROM public.facility_projects p WHERE p.id::text = split_part(name, '/', 1) AND public.can_edit_facility(p.hub)));
CREATE POLICY "Facility editors remove project objects" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'facility-project-files' AND EXISTS (SELECT 1 FROM public.facility_projects p WHERE p.id::text = split_part(name, '/', 1) AND public.can_edit_facility(p.hub)));
CREATE FUNCTION public.can_edit_facility_task(_task_id uuid, _hub text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS (SELECT 1 FROM public.ops_tasks t WHERE t.id = _task_id AND t.hub = _hub) AND public.can_edit_facility(CASE _hub WHEN 'provence' THEN 'fr' WHEN 'czech' THEN 'cz' WHEN 'tuscany' THEN 'it' WHEN 'croatia' THEN 'hr' ELSE '' END) $$;
CREATE POLICY "Facility editors may link their hub requests" ON public.ops_tasks FOR UPDATE TO authenticated USING (task_mode = 'facility_request' AND public.can_edit_facility_task(id, hub)) WITH CHECK (task_mode = 'facility_request' AND public.can_edit_facility_task(id, hub) AND (project_id IS NULL OR EXISTS (SELECT 1 FROM public.facility_projects p WHERE p.id = project_id AND p.hub = CASE hub WHEN 'provence' THEN 'fr' WHEN 'czech' THEN 'cz' WHEN 'tuscany' THEN 'it' WHEN 'croatia' THEN 'hr' ELSE '' END)));